import{_ as o,o as a,c as t,a5 as s}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — Reset Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-4-reset-password/plan.md","filePath":"feature/authentication/3-2-4-reset-password/plan.md"}'),r={name:"feature/authentication/3-2-4-reset-password/plan.md"};function d(n,e,i,c,l,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="plan-—-reset-password" tabindex="-1">Plan — Reset Password <a class="header-anchor" href="#plan-—-reset-password" aria-label="Permalink to &quot;Plan — Reset Password&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — Quên mật khẩu, gửi token/OTP email, đổi mật khẩu + revoke session cũ.</p><h2 id="quyet-đinh-co-che-spec-đe-mo-link-hoac-otp" tabindex="-1">Quyết định cơ chế (spec để mở: link HOẶC OTP) <a class="header-anchor" href="#quyet-đinh-co-che-spec-đe-mo-link-hoac-otp" aria-label="Permalink to &quot;Quyết định cơ chế (spec để mở: link HOẶC OTP)&quot;">​</a></h2><p>Chốt dùng <strong>token qua email</strong> (đồng bộ với code hiện có <code>forgotPassword</code> + <code>resetPassword</code>), KHÔNG dùng OTP riêng cho reset.</p><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><code>POST /api/v1/auth/forgot-password { email }</code> → luôn 200 (không tiết lộ email tồn tại); nếu tồn tại → xoá token reset cũ (nếu có, qua reverse-index) → sinh token reset mới (Redis TTL) + gửi email.</li><li><code>POST /api/v1/auth/reset-password { token, newPassword }</code> → verify token → hash bcrypt → set <code>lastPasswordChange=now</code> (refresh token cũ tự invalid khi so <code>issuedAt</code> với <code>lastPasswordChange</code>, không phải revoke chủ động) → 200.</li><li>Token sai/hết hạn/đã invalidate → 400 <code>RESET_TOKEN_INVALID</code>. Token đã dùng (race) → 400 <code>RESET_TOKEN_USED</code>.</li></ul><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><ol><li>forgot: normalize email → tồn tại? → đọc <code>pwd:reset:user:{userId}</code> lấy <code>oldToken</code> (nếu có) → xoá <code>pwd:reset:{oldToken}</code> → sinh token mới → lưu <code>pwd:reset:{token}=userId</code> và <code>pwd:reset:user:{userId}=token</code> (cùng TTL) → gửi email. Luôn 200.</li><li>reset: verify token → xoá <code>pwd:reset:{token}</code> (atomic) → xoá <code>pwd:reset:user:{userId}</code> (dọn reverse-index) → set password mới + <code>lastPasswordChange=now</code> → audit log <code>PASSWORD_RESET</code> → 200.</li></ol><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><ul><li>Redis: <code>pwd:reset:{token}</code> → userId (TTL = <code>appProperties.passwordResetTtlSeconds</code>); <code>pwd:reset:user:{userId}</code> → token hiện hành (reverse-index, cùng TTL, dùng để invalidate token cũ khi có request mới).</li><li><code>users.passwordHash</code>, <code>users.lastPasswordChange</code> cập nhật.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Spam: email không tồn tại vẫn 200 → không gửi thật (tránh enumeration + spam).</li></ul>',12)])])}const k=o(r,[["render",d]]);export{p as __pageData,k as default};
